  /// decline or during a 3-D Secure challenge, and that transaction stays on
  /// the server.
  String? transactionId;

  List<Object?> _toList() {
    return <Object?>[transactionId];
  }

  Object encode() {
    return _toList();
  }

  static PcCancelled decode(Object result) {
    result as List<Object?>;
    return PcCancelled(transactionId: result[0] as String?);
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  bool operator ==(Object other) {
    if (other is! PcCancelled || other.runtimeType != runtimeType) {
      return false;
    }
    if (identical(this, other)) {
      return true;
    }
    return _deepEquals(transactionId, other.transactionId);
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  int get hashCode => _deepHash(<Object?>[runtimeType, ..._toList()]);

  @override
  String toString() {
    return 'PcCancelled(transactionId: $transactionId)';
  }
}

/// The outcome was never observed. The payment may have succeeded.
///
/// Neither a success nor a decline: a payment that completed looks the same as
/// one that never happened, so it is kept apart from [PcFailure].
class PcPending extends PcPaymentResult {
  PcPending({this.transactionId, required this.reason});

  /// The last transaction this session created, or null when the result was
  /// lost before one was known.
  String? transactionId;

  /// The raw wire name (`poll_timeout`, `result_lost`, `server_verify`), not a
  /// parsed enum.
  String reason;

  List<Object?> _toList() {
    return <Object?>[transactionId, reason];
  }

  Object encode() {
    return _toList();
  }

  static PcPending decode(Object result) {
    result as List<Object?>;
    return PcPending(
      transactionId: result[0] as String?,
      reason: result[1]! as String,
    );
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  bool operator ==(Object other) {
    if (other is! PcPending || other.runtimeType != runtimeType) {
      return false;
    }
    if (identical(this, other)) {
      return true;
    }
    return _deepEquals(transactionId, other.transactionId) &&
        _deepEquals(reason, other.reason);
  }

  @override
  // ignore: avoid_equals_and_hash_code_on_mutable_classes
  int get hashCode => _deepHash(<Object?>[runtimeType, ..._toList()]);

  @override
  String toString() {
    return 'PcPending(transactionId: $transactionId, reason: $reason)';
  }
}

class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is PcEnvironment) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is PcThemeMode) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is PcTestCardPrefill) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    } else if (value is PcColors) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    } else if (value is PcShapes) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    } else if (value is PcPrimaryButton) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    } else if (value is PcTypography) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    } else if (value is PcAppearance) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else if (value is PcConfiguration) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    } else if (value is PcVersionInfo) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is PcAmount) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is PcSuccess) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is PcFailure) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is PcCancelled) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is PcPending) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : PcEnvironment.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : PcThemeMode.values[value];
      case 131:
        return PcTestCardPrefill.decode(readValue(buffer)!);
      case 132:
        return PcColors.decode(readValue(buffer)!);
      case 133:
        return PcShapes.decode(readValue(buffer)!);
      case 134:
        return PcPrimaryButton.decode(readValue(buffer)!);
      case 135:
        return PcTypography.decode(readValue(buffer)!);
      case 136:
        return PcAppearance.decode(readValue(buffer)!);
      case 137:
        return PcConfiguration.decode(readValue(buffer)!);
      case 138:
        return PcVersionInfo.decode(readValue(buffer)!);
      case 139:
        return PcAmount.decode(readValue(buffer)!);
      case 140:
        return PcSuccess.decode(readValue(buffer)!);
      case 141:
        return PcFailure.decode(readValue(buffer)!);
      case 142:
        return PcCancelled.decode(readValue(buffer)!);
      case 143:
        return PcPending.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

class PayCrossHostApi {
  /// Constructor for [PayCrossHostApi]. The [binaryMessenger] named argument is
  /// available for dependency injection. If it is left null, the default
  /// BinaryMessenger will be used which routes to the host platform.
  PayCrossHostApi({
    BinaryMessenger? binaryMessenger,
    String messageChannelSuffix = '',
  }) : pigeonVar_binaryMessenger = binaryMessenger,
       pigeonVar_messageChannelSuffix = messageChannelSuffix.isNotEmpty
           ? '.$messageChannelSuffix'
           : '';
  final BinaryMessenger? pigeonVar_binaryMessenger;

  static const MessageCodec<Object?> pigeonChannelCodec = _PigeonCodec();

  final String pigeonVar_messageChannelSuffix;

  /// Applies configuration to the native SDK.
  ///
  /// Re-applied lazily inside presentPayment, because a hot restart or a second
  /// add-to-app engine can lose the Dart-side flag while the native process
  /// keeps running, and iOS then hits assertionFailure.
  Future<void> configure(PcConfiguration configuration) async {
    final pigeonVar_channelName =
        'dev.flutter.pigeon.paycross_flutter.PayCrossHostApi.configure$pigeonVar_messageChannelSuffix';
    final pigeonVar_channel = BasicMessageChannel<Object?>(
      pigeonVar_channelName,
      pigeonChannelCodec,
      binaryMessenger: pigeonVar_binaryMessenger,
    );
    final Future<Object?> pigeonVar_sendFuture = pigeonVar_channel.send(
      <Object?>[configuration],
    );
    final pigeonVar_replyList = await pigeonVar_sendFuture as List<Object?>?;

    _extractReplyValueOrThrow(
      pigeonVar_replyList,
      pigeonVar_channelName,
      isNullValid: true,
    );
  }

  Future<PcVersionInfo> versionInfo() async {
    final pigeonVar_channelName =
        'dev.flutter.pigeon.paycross_flutter.PayCrossHostApi.versionInfo$pigeonVar_messageChannelSuffix';
    final pigeonVar_channel = BasicMessageChannel<Object?>(
      pigeonVar_channelName,
      pigeonChannelCodec,
      binaryMessenger: pigeonVar_binaryMessenger,
    );
    final Future<Object?> pigeonVar_sendFuture = pigeonVar_channel.send(null);
    final pigeonVar_replyList = await pigeonVar_sendFuture as List<Object?>?;

    final Object? pigeonVar_replyValue = _extractReplyValueOrThrow(
      pigeonVar_replyList,
      pigeonVar_channelName,
      isNullValid: false,
    );
    return pigeonVar_replyValue! as PcVersionInfo;
  }

  /// Presents the native payment UI, resolving when the payment reaches a
  /// terminal state or the shopper cancels. Declines arrive as PcFailure, not
  /// as errors: an error from this method means an integration mistake.
  ///
  /// Can take minutes (the poll deadline is 480s on both platforms). Do not
  /// wrap the returned Future in Future.timeout: a shorter timeout orphans a
  /// live payment that may still charge the card.
  Future<PcPaymentResult> presentPayment(String sessionToken) async {
    final pigeonVar_channelName =
        'dev.flutter.pigeon.paycross_flutter.PayCrossHostApi.presentPayment$pigeonVar_messageChannelSuffix';
    final pigeonVar_channel = BasicMessageChannel<Object?>(
      pigeonVar_channelName,
      pigeonChannelCodec,
      binaryMessenger: pigeonVar_binaryMessenger,
    );
    final Future<Object?> pigeonVar_sendFuture = pigeonVar_channel.send(
      <Object?>[sessionToken],
    );
    final pigeonVar_replyList = await pigeonVar_sendFuture as List<Object?>?;

    final Object? pigeonVar_replyValue = _extractReplyValueOrThrow(
      pigeonVar_replyList,
      pigeonVar_channelName,
      isNullValid: false,
    );
    return pigeonVar_replyValue! as PcPaymentResult;
  }
}
